{{- if .Values.microservices.enabled }}
apiVersion: apps/v1
kind: Deployment
metadata:
  name: {{ .Release.Name }}-authorization
  labels:
    app.kubernetes.io/name: {{ include "rocketchat.name" . }}
    helm.sh/chart: {{ include "rocketchat.chart" . }}
    app.kubernetes.io/instance: {{ .Release.Name }}
    app.kubernetes.io/managed-by: {{ .Release.Service }}
    {{- if .Values.deploymentLabels }}
      {{- toYaml .Values.deploymentLabels | nindent 4 }}
    {{- end }}
spec:
  replicas: {{ .Values.microservices.authorization.replicas }}
  revisionHistoryLimit: 0
  selector:
    matchLabels:
      app.kubernetes.io/name: {{ .Release.Name }}-authorization
      app.kubernetes.io/instance: {{ .Release.Name }}
  strategy:
    rollingUpdate:
      maxSurge: 1
      maxUnavailable: 1
    type: RollingUpdate
  template:
    metadata:
      labels:
        app.kubernetes.io/name: {{ .Release.Name }}-authorization
        app.kubernetes.io/instance: {{ .Release.Name }}
        {{- if .Values.podLabels }}
          {{- toYaml .Values.podLabels | nindent 8 }}
        {{- end }}
      annotations:
        {{ include "rocketchat.annotations" (dict "name" "authorization" "context" $) | indent 8 }}

    spec:
      {{- with .Values.imagePullSecrets }}
      imagePullSecrets:
          {{- toYaml . | nindent 8 }}
      {{- end }}
      tolerations:
        {{ include "rocketchat.tolerations" (dict "name" "authorization" "context" $) | indent 8 }}
      nodeSelector:
        {{ include "rocketchat.nodeSelector" (dict "name" "authorization" "context" $) | indent 8 }}
      affinity:
        {{ include "rocketchat.nodeAffinity" (dict "name" "authorization" "context" $) | indent 8 }}      
      containers:
      - name: authorization-service
        image: "{{ include "rocketchat.image" (dict "repository" .Values.microservices.authorization.image.repository "tag" .Values.image.tag "appVersion" .Chart.AppVersion "global" .Values.global) }}"
        env:
        {{- if .Values.existingMongodbSecret }}
        - name: MONGO_URL
          valueFrom:
            secretKeyRef:
              name: {{ .Values.existingMongodbSecret }}
              key: mongo-uri
        {{- else }}
        - name: MONGO_URL
          valueFrom:
            secretKeyRef:
              name: {{ template "rocketchat.fullname" . }}
              key: mongo-uri
        {{- end }}
        {{- include "rocketchat.transporter.connectionString" (dict "Values" $.Values "Release" $.Release) | nindent 8 }}
        {{- if eq (include "rocketchat.streamHub.enabled" .) "true" }}
        - name: DB_WATCHERS
          value: "true"
        {{- end }}
        - name: MOLECULER_LOG_LEVEL
          value: {{ .Values.microservices.logLevel | quote }}
        - name: HEARTBEAT_INTERVAL
          value: {{ .Values.microservices.heartbeatInterval | quote }}
        - name: HEARTBEAT_TIMEOUT
          value: {{ .Values.microservices.heartbeatTimeout | quote }}
        - name: RETRY_ENABLED
          value: 'yes'
        {{- if .Values.prometheusScraping.enabled }}
        - name: MS_METRICS
          value: "true"
        - name: MS_METRICS_PORT
          value: {{ .Values.prometheusScraping.msPort | default "9458" | quote }}
        {{- end }}
        ports:
        {{- if .Values.prometheusScraping.enabled }}
        - name: ms-metrics
          containerPort: {{ .Values.prometheusScraping.msPort }}
        {{- end }}
        volumeMounts: 
        {{- if .Values.extraVolumeMounts }}
        {{- include "common.tplvalues.render" (dict "value" .Values.extraVolumeMounts "context" $) | nindent 8 }}
        {{- end }}   
        securityContext:
          {{- toYaml .Values.microservices.authorization.securityContext | nindent 10 }}
        resources: {{- toYaml .Values.microservices.authorization.resources | nindent 10 }}
      volumes:
      {{- if .Values.extraVolumes }}
      {{- include "common.tplvalues.render" (dict "value" .Values.extraVolumes "context" $) | nindent 6 }}
      {{- end }}
      dnsPolicy: ClusterFirst
      restartPolicy: Always
      schedulerName: default-scheduler
      securityContext: {}
      terminationGracePeriodSeconds: 30
{{- end }}

{{/* vi: ts=8 et sw=2 smarttab */}}

---
{{- $retentionGb :=
    index
      (regexSplit "G+" (printf "%v" $.Values.operator.prometheus.prometheusSpec.retentionSize) -1)
      0
-}}
{{- $retentionStorage :=
  index
    (regexSplit "G+" (printf "%v" $.Values.operator.prometheus.prometheusSpec.storageSpec.volumeClaimTemplate.spec.resources.requests.storage) -1)
    0
-}}
{{/* GB is base10 Gi is base2, this results in Gi being slightly around 7% */}}
{{/* But even creating both with GB, giving extra expace to prometheus would avoid it not loading because of no-space-on-device */}}
{{/* 15% is safe for both */}}


{{- if lt
  (float64 (mul $retentionStorage 1.15))
  (float64 $retentionGb)
-}}
  {{- fail (printf
    "\n%s=%s should be at least 15%% higher than %s=%s"
    ".Values.operator.prometheus.prometheusSpec.storageSpec.volumeClaimTemplate.spec.resources.requests.storage"
    .Values.operator.prometheus.prometheusSpec.storageSpec.volumeClaimTemplate.spec.resources.requests.storage
    ".Values.operator.prometheus.prometheusSpec.retentionSize"
    .Values.operator.prometheus.prometheusSpec.retentionSize
    ) -}}
{{- end -}}


{{- if and .Values.operator.grafana.enabled .Values.grafana.deploy.enabled -}}
  {{- fail (printf
    "\n%s=%s and %s=%s are both enabled, please choose one"
    ".Values.operator.grafana.enabled"
    .Values.operator.grafana.enabled
    ".Values.grafana.deploy.enabled"
    .Values.grafana.deploy.enabled
    ) -}}
{{- end -}}

{{- if .Values.microservices.enabled }}
  {{- if .Values.prometheusScraping.enabled }}
    {{- $service := .Values.service -}}
apiVersion: v1
kind: Service
metadata:
  name: {{ .Release.Name }}-authorization
  annotations:
    prometheus.io/path: "/metrics"
    prometheus.io/scrape: "true"
    prometheus.io/port: "{{ .Values.prometheusScraping.msPort }}"
    {{- with $service.annotations }}
      {{- toYaml . | nindent 4 }}
    {{- end }}
spec:
  type: ClusterIP
  ports:
  - name: metrics
    targetPort: {{ .Values.prometheusScraping.msPort }}
    port: {{ .Values.prometheusScraping.msPort }}
    protocol: TCP
  selector:
    app.kubernetes.io/name: {{ .Release.Name }}-authorization
    app.kubernetes.io/instance: {{ .Release.Name }}
  {{- end }}
{{- end }}

