{{- $prometheus := eq (include "rocketchat-livekit.isTrue" .Values.monitoring.prometheus.enabled) "true" }}
{{- $tcp := eq (include "rocketchat-livekit.isTrue" .Values.media.tcp.enabled) "true" }}
{{- $turn := eq (include "rocketchat-livekit.isTrue" .Values.turn.enabled) "true" }}
apiVersion: apps/v1
kind: Deployment
metadata:
  name: {{ include "rocketchat-livekit.fullname" . }}
  labels:
    {{- include "rocketchat-livekit.labels" . | nindent 4 }}
spec:
  # A single node: a multi-node LiveKit needs Redis (`config.redis.address`)
  # and a media address per node, which this chart doesn't do.
  replicas: 1
  # Two LiveKit nodes without Redis don't know each other's rooms, so never
  # run the old and the new one side by side.
  strategy:
    type: Recreate
  selector:
    matchLabels:
      {{- include "rocketchat-livekit.selectorLabels" . | nindent 6 }}
  template:
    metadata:
      annotations:
        checksum/config: {{ include "rocketchat-livekit.config" . | sha256sum }}
        checksum/credentials: {{ toYaml .Values.credentials | sha256sum }}
        {{- with .Values.podAnnotations }}
        {{- toYaml . | nindent 8 }}
        {{- end }}
      labels:
        {{- include "rocketchat-livekit.labels" . | nindent 8 }}
        {{- with .Values.podLabels }}
        {{- toYaml . | nindent 8 }}
        {{- end }}
    spec:
      {{- with .Values.imagePullSecrets }}
      imagePullSecrets:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      serviceAccountName: {{ include "rocketchat-livekit.serviceAccountName" . }}
      {{- with .Values.podSecurityContext }}
      securityContext:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      terminationGracePeriodSeconds: {{ .Values.terminationGracePeriodSeconds }}
      containers:
        - name: livekit
          {{- with .Values.securityContext }}
          securityContext:
            {{- toYaml . | nindent 12 }}
          {{- end }}
          image: "{{ .Values.image.name }}:{{ .Values.image.tag | default .Chart.AppVersion }}"
          imagePullPolicy: {{ .Values.image.pullPolicy }}
          # `node_ip` must be an IP, so resolve the media FQDN here. It's done
          # once: if the load balancer's address changes, restart the pod.
          command:
            - /bin/sh
            - -c
            - |
              set -e
              if [ -z "$NODE_IP" ] && [ -n "$NODE_HOST" ]; then
                until NODE_IP="$(getent ahostsv4 "$NODE_HOST" | awk 'NR==1 { print $1 }')" && [ -n "$NODE_IP" ]; do
                  echo "Waiting for $NODE_HOST to resolve..."
                  sleep 5
                done
                echo "Advertising $NODE_IP ($NODE_HOST) to clients"
                export NODE_IP
              fi
              exec /livekit-server --config /etc/livekit/livekit.yaml
          env:
            - name: LIVEKIT_API_KEY
              valueFrom:
                secretKeyRef:
                  name: {{ include "rocketchat-livekit.credentialsSecretName" . }}
                  key: apiKey
            - name: LIVEKIT_API_SECRET
              valueFrom:
                secretKeyRef:
                  name: {{ include "rocketchat-livekit.credentialsSecretName" . }}
                  key: apiSecret
            - name: LIVEKIT_KEYS
              value: "$(LIVEKIT_API_KEY): $(LIVEKIT_API_SECRET)"
            {{- with tpl .Values.media.nodeIP . }}
            - name: NODE_IP
              value: {{ . | quote }}
            {{- end }}
            {{- with tpl .Values.media.externalAddress . }}
            - name: NODE_HOST
              value: {{ . | quote }}
            {{- end }}
          ports:
            - name: http
              containerPort: 7880
              protocol: TCP
            - name: rtc-udp
              containerPort: {{ .Values.media.udpPort }}
              protocol: UDP
            {{- if $tcp }}
            - name: rtc-tcp
              containerPort: {{ .Values.media.tcp.port }}
              protocol: TCP
            {{- end }}
            {{- if $turn }}
            - name: turn-tls
              containerPort: {{ .Values.turn.tlsPort }}
              protocol: TCP
            {{- end }}
            {{- if $prometheus }}
            - name: prometheus
              containerPort: {{ .Values.monitoring.prometheus.port }}
              protocol: TCP
            {{- end }}
          # Covers the wait for the media FQDN to resolve.
          startupProbe:
            httpGet:
              path: /
              port: http
            periodSeconds: 5
            failureThreshold: 120
          livenessProbe:
            httpGet:
              path: /
              port: http
            periodSeconds: 10
            failureThreshold: 3
          readinessProbe:
            httpGet:
              path: /
              port: http
            periodSeconds: 5
          {{- with .Values.resources }}
          resources:
            {{- toYaml . | nindent 12 }}
          {{- end }}
          volumeMounts:
            - name: config
              mountPath: /etc/livekit/livekit.yaml
              subPath: livekit.yaml
              readOnly: true
            {{- if $turn }}
            - name: turn-tls
              mountPath: /etc/livekit/tls
              readOnly: true
            {{- end }}
            {{- with .Values.volumeMounts }}
            {{- toYaml . | nindent 12 }}
            {{- end }}
      volumes:
        - name: config
          configMap:
            name: {{ include "rocketchat-livekit.fullname" . }}
        {{- if $turn }}
        - name: turn-tls
          secret:
            secretName: {{ include "rocketchat-livekit.turnTlsSecretName" . }}
        {{- end }}
        {{- with .Values.volumes }}
        {{- toYaml . | nindent 8 }}
        {{- end }}
      {{- with .Values.nodeSelector }}
      nodeSelector:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      {{- with .Values.affinity }}
      affinity:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      {{- with .Values.tolerations }}
      tolerations:
        {{- toYaml . | nindent 8 }}
      {{- end }}

{{- if and .Values.microservices.enabled (eq (include "rocketchat.streamHub.enabled" .) "true") }}
{{- if semverCompare ">=8.0.0" (.Values.image.tag | default .Chart.AppVersion) }}
{{- fail "Stream Hub microservice is only supported in Rocket.Chat versions prior to 8.0.0, please set microservices.streamHub.enabled to false before upgrading to 8.0.0 or later." -}}
{{- end }}




apiVersion: apps/v1
kind: Deployment
metadata:
  name: {{ .Release.Name }}-stream-hub
  labels:
    app.kubernetes.io/name: {{ include "rocketchat.name" . }}
    helm.sh/chart: {{ include "rocketchat.chart" . }}
    app.kubernetes.io/instance: {{ .Release.Name }}
    app.kubernetes.io/managed-by: {{ .Release.Service }}
    {{- if .Values.deploymentLabels }}
      {{- toYaml .Values.deploymentLabels | nindent 4 }}
    {{- end }}
spec:
  replicas: 1
  revisionHistoryLimit: 0
  selector:
    matchLabels:
      app.kubernetes.io/name: {{ .Release.Name }}-stream-hub
      app.kubernetes.io/instance: {{ .Release.Name }}
  strategy:
    rollingUpdate:
      maxSurge: 1
      maxUnavailable: 0
    type: RollingUpdate
  template:
    metadata:
      labels:
        app.kubernetes.io/name: {{ .Release.Name }}-stream-hub
        app.kubernetes.io/instance: {{ .Release.Name }}
        {{- if .Values.podLabels }}
          {{- toYaml .Values.podLabels | nindent 8 }}
        {{- end }}
      annotations:
       {{ include "rocketchat.annotations" (dict "name" "streamHub" "context" $) | indent 8 }}
    spec:
      {{- with .Values.imagePullSecrets }}
      imagePullSecrets:
          {{- toYaml . | nindent 8 }}
      {{- end }}
      tolerations:
        {{ include "rocketchat.tolerations" (dict "name" "streamHub" "context" $) | indent 8 }}
      nodeSelector:
        {{ include "rocketchat.nodeSelector" (dict "name" "streamHub" "context" $) | indent 8 }}      
      affinity:
        {{ include "rocketchat.nodeAffinity" (dict "name" "streamHub" "context" $) | indent 8 }}   
      containers:
      - name: stream-hub
        image: "{{ include "rocketchat.image" (dict "repository" .Values.microservices.streamHub.image.repository "tag" .Values.image.tag "appVersion" .Chart.AppVersion "global" .Values.global) }}"
        env:
        {{- if .Values.existingMongodbSecret }}
        - name: MONGO_URL
          valueFrom:
            secretKeyRef:
              name: {{ .Values.existingMongodbSecret }}
              key: mongo-uri
        {{- else }}
        - name: MONGO_URL
          valueFrom:
            secretKeyRef:
              name: {{ template "rocketchat.fullname" . }}
              key: mongo-uri
        {{- end }}
        {{- include "rocketchat.transporter.connectionString" (dict "Values" $.Values "Release" $.Release) | nindent 8 }}
        - name: DB_WATCHERS
          value: "true"
        - name: MOLECULER_LOG_LEVEL
          value: {{ .Values.microservices.logLevel | quote }}
        - name: HEARTBEAT_INTERVAL
          value: {{ .Values.microservices.heartbeatInterval | quote }}
        - name: HEARTBEAT_TIMEOUT
          value: {{ .Values.microservices.heartbeatTimeout | quote }}
        - name: RETRY_ENABLED
          value: 'yes'
        {{- if .Values.prometheusScraping.enabled }}
        - name: MS_METRICS
          value: "true"
        - name: MS_METRICS_PORT
          value: {{ .Values.prometheusScraping.msPort | default "9458" | quote }}
        {{- end }}
        ports:
        {{- if .Values.prometheusScraping.enabled }}
        - name: ms-metrics
          containerPort: {{ .Values.prometheusScraping.msPort }}
        {{- end }}
        volumeMounts: 
        {{- if .Values.extraVolumeMounts }}
        {{- include "common.tplvalues.render" (dict "value" .Values.extraVolumeMounts "context" $) | nindent 8 }}
        {{- end }}   
        securityContext:
          {{- toYaml .Values.microservices.streamHub.securityContext | nindent 10 }}
        resources: {{- toYaml .Values.microservices.streamHub.resources | nindent 10 }}
      volumes:
      {{- if .Values.extraVolumes }}
      {{- include "common.tplvalues.render" (dict "value" .Values.extraVolumes "context" $) | nindent 6 }}
      {{- end }}
      dnsPolicy: ClusterFirst
      restartPolicy: Always
      schedulerName: default-scheduler
      securityContext: {}
      terminationGracePeriodSeconds: 30

{{- else -}}
{{- if semverCompare "<=7.7.0" (.Values.image.tag | default .Chart.AppVersion) }}
{{- fail "Stream Hub microservice is required when running Rocket.Chat versions prior to 7.7.0, please set microservices.streamHub.enabled to true." -}}
{{- end }}
{{- end }}

